/// Catastrophe (colorless Skill, Self, Exhaust). Auto-play 2 random cards
/// from draw pile. Mirrors `sts2_env/cards/colorless.py:73-81` at pin
/// `01c094d` (`for _ in range(2): combat.auto_play_card(rng.choice(...))`).
/// The Rust port has no `auto_play_card` primitive; the inline play of
/// arbitrary cards-from-piles needs the full dispatch + targeting +
/// keyword machinery routed through a non-hand source pile, which is
/// Phase 7 work. Registered as a marker for coverage census.
/// Bead `sts2-rs-2h42`.
pub(crate) fn play_catastrophe(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    // C# `Catastrophe.cs` `OnPlay`: `for i in 0..Cards: chosen =
    // Draw.Where(!Unplayable).StableShuffle(Shuffle).FirstOrDefault();
    // if (chosen == null) chosen = Draw.StableShuffle(...).First();
    // CardCmd.AutoPlay(chosen)`. The picked card resolves and routes to
    // its natural pile (discard / self-exhaust) — it is NOT moved to
    // hand. Bead `sts2-rs-q6bix` (was a `move_card_to_hand` port).
    //
    // The `is_unplayable` filter is honored via the
    // `card_effects::card_unplayable(id)` engine-side registry populated
    // by `install_unplayable_keywords` (bead `sts2-rs-6ynt.8-unplayable`).
    // We collect the playable draw uids first, falling back to the full
    // draw when none are playable (matches C#'s null-fallback branch).
    // Bead `sts2-rs-zqxkw`: C# `Catastrophe.cs` `CardsVar(2)` with `OnUpgrade
    // UpgradeValueBy(1m)` → 2 base / 3 upgraded. Prior body hardcoded 2.
    //
    // The count is re-read every iteration (see [`catastrophe_cards`]), so the
    // loop is keyed on the Catastrophe instance, not on a count taken here.
    let Some(catastrophe) = sts2_core::card_effects::resolving_card_uid(state) else {
        return EffectResult::Resolved;
    };
    catastrophe_run(state, catastrophe, 0);
    EffectResult::Resolved
}

/// C# `base.DynamicVars.Cards.IntValue`: 2, or 3 once upgraded. `OnPlay`'s
/// `for` condition re-reads it before EVERY iteration (Catastrophe.cs:23, both
/// builds), so an upgrade that lands mid-play — a Dampen re-upgrading the card
/// when its caster dies to an auto-played attack, an auto-played Apotheosis —
/// adds an iteration (v0.111.0 random-loadout 1028).
fn catastrophe_cards(state: &CombatState, catastrophe: CardUid) -> u32 {
    let upgraded = state
        .cards
        .get(catastrophe.0.get() as usize - 1)
        .is_some_and(|c| c.upgraded);
    if upgraded {
        3
    } else {
        2
    }
}

/// Run `iters` Catastrophe draw-pile auto-play iterations (each: filter +
/// `StableShuffle` + `AutoPlay` the first card), SUSPENDING the loop if an
/// auto-played card surfaces a nested card-select.
